    for (let y = 0; y < 16; y++) {
      map[y] = [];
      for (let x = 0; x < 16; x++) {
        map[y][x] = y === 8 ? 'water' : 'grass';
      }
    }

    const result = ensureReachability(map, { x: 2, y: 2 }, { x: 13, y: 13 }, 16, 16);
    expect(result).toBe(false);
  });
});

describe('PRNG', () => {
  it('produces deterministic sequence', () => {
    const rng1 = new PRNG(42);
    const rng2 = new PRNG(42);

    for (let i = 0; i < 100; i++) {
      expect(rng1.next()).toBe(rng2.next());
    }
  });

  it('int returns values in range', () => {
    const rng = new PRNG(42);
    for (let i = 0; i < 100; i++) {
      const v = rng.int(5, 15);
      expect(v).toBeGreaterThanOrEqual(5);
      expect(v).toBeLessThanOrEqual(15);
    }
  });
});

/**
 * Tests for A* pathfinding: shortest path, corner cutting, unreachable handling.
 */
import { describe, it, expect } from 'vitest';
import { findPath } from '../src/pathfinding/astar.js';
import { Tile, TileType } from '../src/engine/types.js';

function makeTiles(width: number, height: number, type: TileType = 'grass'): Tile[][] {
  const tiles: Tile[][] = [];
  for (let y = 0; y < height; y++) {
    tiles[y] = [];
    for (let x = 0; x < width; x++) {
      tiles[y][x] = { type, resource: 0, fog: 2, lastSeen: type, lastSeenEntity: null };
    }
  }
  return tiles;
}

describe('A* Pathfinding', () => {
  it('finds direct path on empty map', () => {
    const tiles = makeTiles(16, 16);
    const result = findPath(tiles, 1, 1, 14, 14, 16, 16);

    expect(result.found).toBe(true);
    expect(result.path.length).toBeGreaterThan(0);
    expect(result.path[0]).toEqual({ x: 1, y: 1 });
    expect(result.path[result.path.length - 1]).toEqual({ x: 14, y: 14 });
  });

  it('finds shortest path (Manhattan distance for straight path)', () => {
    const tiles = makeTiles(16, 16);
    // Straight horizontal path
    const result = findPath(tiles, 1, 8, 14, 8, 16, 16);

    expect(result.found).toBe(true);
    // Path length should be reasonable (not excessively long)
    expect(result.path.length).toBeLessThanOrEqual(16);
  });

  it('finds path around obstacles', () => {
    const tiles = makeTiles(16, 16);
    // Create wall with gap
    for (let x = 0; x < 16; x++) {
      if (x !== 8) { // Gap at x=8
        tiles[8][x].type = 'rock';
      }
    }

    const result = findPath(tiles, 1, 5, 14, 12, 16, 16);
    expect(result.found).toBe(true);
    expect(result.path.length).toBeGreaterThan(0);
  });

  it('returns not found when destination is unreachable', () => {
    const tiles = makeTiles(16, 16);
    // Surround destination with rock
    tiles[14][14].type = 'rock';
    tiles[13][14].type = 'rock';
    tiles[14][13].type = 'rock';
    tiles[15][14].type = 'rock';
    tiles[14][15].type = 'rock';
    tiles[13][13].type = 'rock';
    tiles[15][15].type = 'rock';
    tiles[13][15].type = 'rock';
    tiles[15][13].type = 'rock';

    const result = findPath(tiles, 1, 1, 14, 14, 16, 16);
    // Should either fail or find alternate path
    // If it finds a path, it must not go through rock
    if (result.found) {
      for (const p of result.path) {
        expect(tiles[p.y][p.x].type).not.toBe('rock');
        expect(tiles[p.y][p.x].type).not.toBe('water');
      }
    }
  });

  it('does not cut corners through blocked diagonals', () => {
    const tiles = makeTiles(8, 8);
    // Block diagonal corners: place rocks to force corner-cutting check
    tiles[3][4].type = 'rock';
    tiles[4][3].type = 'rock';

    const result = findPath(tiles, 2, 2, 6, 6, 8, 8);
    expect(result.found).toBe(true);

    // Verify no diagonal move passes through a blocked adjacent tile
    for (let i = 1; i < result.path.length; i++) {
      const prev = result.path[i - 1];
      const curr = result.path[i];
      const dx = curr.x - prev.x;
      const dy = curr.y - prev.y;

      // If diagonal move
      if (dx !== 0 && dy !== 0) {
        // Both adjacent cells must be walkable
        expect(tiles[prev.y][prev.x + dx].type).not.toBe('rock');
        expect(tiles[prev.y + dy][prev.x].type).not.toBe('rock');
      }
    }
  });

  it('handles start equals goal', () => {
    const tiles = makeTiles(8, 8);
    const result = findPath(tiles, 4, 4, 4, 4, 8, 8);

    expect(result.found).toBe(true);
    expect(result.path.length).toBeGreaterThanOrEqual(1);
  });

  it('handles water tiles as unwalkable', () => {
    const tiles = makeTiles(16, 16);
    // Create water barrier
    for (let x = 0; x < 16; x++) {
      tiles[8][x].type = 'water';
    }

    const result = findPath(tiles, 1, 5, 14, 12, 16, 16);
    // Should fail or find path around
    if (result.found) {
      for (const p of result.path) {
        expect(tiles[p.y][p.x].type).not.toBe('water');
      }
    }
  });
});

/**
 * Tests for combat damage math and supply accounting.
 */
import { describe, it, expect } from 'vitest';
import { calcDamage, applyDamage, isInAttackRange } from '../src/combat/combat.js';
import { Entity, Faction, GameState, TILE_SIZE } from '../src/engine/types.js';
import { getStats } from '../src/entities/stats.js';
import { createEntity, resetIdCounter } from '../src/entities/manager.js';

function makeTestState(): GameState {
  const tiles = [];
  for (let y = 0; y < 16; y++) {
    tiles[y] = [];
    for (let x = 0; x < 16; x++) {
      tiles[y][x] = { type: 'grass', resource: 0, fog: 2, lastSeen: 'grass', lastSeenEntity: null };
    }
  }

  return {
    seed: 42,
    mapWidth: 16,
    mapHeight: 16,
    tiles,
    entities: [],
    projectiles: [],
    nextEntityId: 1,
    nextProjectileId: 1,
    gameTime: 0,
    paused: false,
    speed: 1,
    playerFaction: 'humans',
    aiFaction: 'orcs',
    resources: { humans: [1000, 1000, 0, 20], orcs: [1000, 1000, 0, 20] },
    selectedEntityIds: [],
    level: 0,
    gameOver: false,
    winner: null
  };
}

function makeTestEntity(type: 'worker' | 'melee' | 'ranged' | 'heavy', faction: Faction, x: number, y: number): Entity {
  const stats = getStats(type, faction);
  return {
    id: Math.floor(Math.random() * 10000),
    type,
    faction,
    x,
    y,
    tileX: Math.floor(x / TILE_SIZE),
    tileY: Math.floor(y / TILE_SIZE),
    hp: stats.hp,
    maxHp: stats.maxHp,
    stats,
    state: 'idle',
    targetX: null,
    targetY: null,
    attackTarget: null,
    attackCooldownLeft: 0,
    path: [],
    pathIndex: 0,
    carrying: null,
    carryAmount: 0,
    harvestTileX: null,
    harvestTileY: null,
    buildingType: null,
    buildProgress: 0,
    trainQueue: [],
    deathTimer: 0,
    visible: true
  };
}

describe('Combat Damage Math', () => {
  it('calculates basic damage (attacker damage minus defender armor)', () => {
    const attacker = makeTestEntity('melee', 'humans', 100, 100);
    const defender = makeTestEntity('melee', 'orcs', 120, 100);

    const damage = calcDamage(attacker, defender);
    // Footman: 12 damage, Grunt: 2 armor -> 10
    expect(damage).toBe(10);
  });

  it('enforces minimum damage of 1', () => {
    const attacker = makeTestEntity('worker', 'humans', 100, 100);
    const defender = makeTestEntity('heavy', 'orcs', 120, 100);

    const damage = calcDamage(attacker, defender);
    // Peasant: 5 damage, Ogre: 4 armor -> 1
    expect(damage).toBe(1);
  });

  it('heavy unit deals high damage', () => {
    const attacker = makeTestEntity('heavy', 'humans', 100, 100);
    const defender = makeTestEntity('worker', 'orcs', 120, 100);

    const damage = calcDamage(attacker, defender);
    // Knight: 25 damage, Peon: 0 armor -> 25
    expect(damage).toBe(25);
  });

  it('ranged unit has correct damage', () => {
    const attacker = makeTestEntity('ranged', 'humans', 100, 100);
    const defender = makeTestEntity('melee', 'orcs', 120, 100);

    const damage = calcDamage(attacker, defender);
    // Archer: 15 damage, Grunt: 2 armor -> 13
    expect(damage).toBe(13);
  });

  it('applyDamage reduces HP correctly', () => {
    const entity = makeTestEntity('melee', 'humans', 100, 100);
    const initialHp = entity.hp;

    const died = applyDamage(entity, 10);
    expect(entity.hp).toBe(initialHp - 10);
    expect(died).toBe(false);
  });

  it('applyDamage returns true when HP reaches zero', () => {
    const entity = makeTestEntity('worker', 'humans', 100, 100);
    entity.hp = 5;

    const died = applyDamage(entity, 10);
    expect(entity.hp).toBe(-5);
    expect(died).toBe(true);
  });

  it('melee range check works for adjacent units', () => {
    const attacker = makeTestEntity('melee', 'humans', 100, 100);
    const target = makeTestEntity('melee', 'orcs', 132, 100); // 1 tile away
    const tiles = makeTestState().tiles;

    const inRange = isInAttackRange(attacker, target, tiles);
    expect(inRange).toBe(true);
  });

